import { ImageResponse } from "next/og";

/** Placeholder PWA icon (006: HTTPS/PWA installability) — a plain
 * colored square with initials, generated by code so no image asset or
 * design tool is needed. Easy to replace with a real logo later: swap
 * this one function. */
export function renderPwaIcon(size: number, background: string) {
  return new ImageResponse(
    (
      <div
        style={{
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          background,
          color: "#ffffff",
          fontSize: size * 0.45,
          fontWeight: 700,
          fontFamily: "sans-serif",
        }}
      >
        LA
      </div>
    ),
    { width: size, height: size }
  );
}
